const LON0 = 23.5;
const LAT1 = 46.5;
const SCALE = 54.0;
const COS = Math.cos((38 * Math.PI) / 180);

/** Longitude/latitude to base-map units. */
export const projectAnatolia = (lon: number, lat: number): [number, number] => [
  (lon - LON0) * COS * SCALE,
  (LAT1 - lat) * SCALE,
];

/** Base-map units for one kilometre (north-south), for the scale bar. */
export const ANATOLIA_UNITS_PER_KM = SCALE / 111.2;
